                    count += 1
        elif first_char == '_':
            if '0' <= second_char <= '9':
                if second_char == str_i[1]:
                    count += 1
            else:
                count += 1
        else:
            # first_char is neither digit nor underscore, so must be 'X'
            if '0' <= second_char <= '9':
                if second_char == str_i[1]:
                    count += 1
            elif second_char == '_':
                count += 1

    print(count)
    exit()

else:
